import 'package:cloud_firestore/cloud_firestore.dart';
import '../../../services/goals/goal_repository.dart';
class AurenDailyPlan{final String goalId,goalTitle,focus;final List<String> steps;final DateTime generatedAt;const AurenDailyPlan({required this.goalId,required this.goalTitle,required this.focus,required this.steps,required this.generatedAt});Map<String,dynamic> toMap()=>{'goalId':goalId,'goalTitle':goalTitle,'focus':focus,'steps':steps,'generatedAt':Timestamp.fromDate(generatedAt.toUtc())};}
class DailyPlanService{final FirebaseFirestore _db;final GoalRepository _goals;DailyPlanService({FirebaseFirestore? firestore,GoalRepository? goals}):_db=firestore??FirebaseFirestore.instance,_goals=goals??GoalRepository();
Future<AurenDailyPlan> build(String uid)async{final goals=await _goals.watch(uid).first;final active=goals.where((g)=>g.status=='active').toList()..sort((a,b)=>a.progress.compareTo(b.progress));final g=active.isEmpty?null:active.first;final title=g?.title??'لا يوجد هدف نشط';final focus=g==null?'أنشئ هدفًا واحدًا واضحًا لليوم.':g.progress<30?'ابدأ بأصغر خطوة قابلة للتنفيذ.':g.progress<70?'ادفع الهدف خطوة عملية إلى الأمام.':'أكمل آخر جزء وحوّل التقدم إلى نتيجة.';final steps=g==null?['أنشئ هدفًا واحدًا','اكتب النتيجة المطلوبة','حدد أول خطوة لمدة 15 دقيقة']:['حدد نتيجة اليوم لهذا الهدف','نفّذ جلسة تركيز واحدة','سجّل ما أنجزته وحدّث التقدم'];final p=AurenDailyPlan(goalId:g?.id??'',goalTitle:title,focus:focus,steps:steps,generatedAt:DateTime.now());await _db.collection('users').doc(uid).collection('daily_plans').doc('current').set(p.toMap());return p;}}